import{describe,it,expect}from"vitest";import{censusYears,stateLiteracyData,sourcingDisclaimer,getRankedStatesByYear,interpolateYearData,calculateLiteracyGrowth,filterStatesData}from"../../frontend/literacy-chart-race/literacy-chart-race.js";describe("Census Years & Dataset Integrity",()=>{it("contains at least 3 decennial census years (contains 7 years: 1951–2011)",()=>{expect(censusYears.length).toBeGreaterThanOrEqual(3),expect(censusYears).toEqual([1951,1961,1971,1981,1991,2001,2011])}),it("contains literacy rates across all census years for 18 states/national entries",()=>{expect(stateLiteracyData.length).toBeGreaterThanOrEqual(15),stateLiteracyData.forEach(e=>{expect(e).toHaveProperty("state"),expect(e).toHaveProperty("region"),expect(e).toHaveProperty("flag"),expect(e).toHaveProperty("rates"),censusYears.forEach(t=>{expect(e.rates).toHaveProperty(t.toString()),expect(typeof e.rates[t]).toBe("number"),expect(e.rates[t]).toBeGreaterThan(0),expect(e.rates[t]).toBeLessThanOrEqual(100)})})})}),describe("Sourcing Disclaimer & Disclaimer Notice",()=>{it('contains mandatory census data sourcing and "as of latest census" disclaimer',()=>{expect(sourcingDisclaimer).toBeDefined(),expect(sourcingDisclaimer.text.toLowerCase()).toContain("census of india"),expect(sourcingDisclaimer.disclaimer.toLowerCase()).toContain("as of census 2011")})}),describe("Bar Chart Race Ranking & Interpolation Engine",()=>{it("returns sorted ranked list of states for a given census year",()=>{const e=getRankedStatesByYear(2011);expect(e.length).toBe(stateLiteracyData.length),expect(e[0].state).toBe("Kerala"),expect(e[0].rate).toBe(94);for(let t=0;t<e.length-1;t++)expect(e[t].rate).toBeGreaterThanOrEqual(e[t+1].rate)}),it("interpolates values between startYear and endYear for smooth bar race steps",()=>{const e=interpolateYearData(1951,1961,.5);expect(e.length).toBe(stateLiteracyData.length);const t=e.find(e=>"Kerala"===e.state);expect(t).toBeDefined(),expect(t.rate).toBeCloseTo(51.13,1)}),it("calculates total literacy growth from 1951 to 2011 correctly",()=>{const e=calculateLiteracyGrowth(47.18,94);expect(e).toBe(46.82);const t=calculateLiteracyGrowth(18.33,74.04);expect(t).toBe(55.71)})}),describe("Search & Region Filter Helper",()=>{it("filters state literacy data by query or region",()=>{const e=filterStatesData("Northeast");expect(e.length).toBeGreaterThan(0),expect(e.some(e=>"Mizoram"===e.state)).toBe(!0);const t=filterStatesData("Kerala");expect(t.length).toBe(1)}),it("returns empty array when query matches nothing",()=>{const e=filterStatesData("NonExistentStateXYZ");expect(e).toEqual([])})});